export class UserId {
  readonly #value: string;
  private constructor(value: string) { this.#value = value; }
  static parse(raw: string): UserId {
    if (!raw) throw new RangeError('empty user id');
    return new UserId(raw);
  }
  toString(): string { return this.#value; }
}
